'use client';
const require_popover_trigger_context = require("./popover-trigger-context.cjs");
const require_popover = require("./popover.cjs");
const require_popover_trigger = require("./popover-trigger.cjs");
//#region src/components/popover/index.ts
/**
* Popover component, used to display content in a popover over an element.
*
* @example
* <Popover.TriggerContext>
*   <Popover.Trigger>Open Popover</Popover.Trigger>
*   <Popover>
*     Content
*   </Popover>
* </Popover.TriggerContext>
*/
const PopoverComponent = Object.assign(require_popover.Popover, {
	TriggerContext: require_popover_trigger_context.PopoverTriggerContext,
	Trigger: require_popover_trigger.PopoverTrigger
});
PopoverComponent.TriggerContext.displayName = "Popover.TriggerContext";
PopoverComponent.Trigger.displayName = "Popover.Trigger";
//#endregion
exports.Popover = PopoverComponent;
exports.PopoverTrigger = require_popover_trigger.PopoverTrigger;
exports.PopoverTriggerContext = require_popover_trigger_context.PopoverTriggerContext;
